mapper.select:
SELECT audit_category, event_type, transaction_id, operator_id, operator_name, target_type, target_id,
       detail_before, detail_after, result, fail_reason, client_ip, user_agent, trace_id, event_time
FROM sys_audit

    AND audit_category = #{category}
    AND event_type = #{eventType}
    AND operator_id = #{operatorId}
    AND target_type = #{targetType}
    AND event_time >= #{from}
    AND event_time <= #{to}
    AND event_time < #{cursor}

ORDER BY event_time DESC LIMIT #{limit}
